// AUTO-GENERATED by scripts/build-api-docs.mjs from /docs. Do not edit; run `npm run gen:docs -w aaira-gallery`.
const area: Record<string, Record<string, string>> = {"web-forms-mapping":{"overview":"<div class=\"table-scroll\"><table><thead><tr><th>ASP.NET Web Forms</th><th>TypeScript</th><th>Notes</th></tr></thead><tbody><tr><td><code>&lt;asp:Menu&gt;</code></td><td><code>MenuController</code></td><td><code>Orientation</code>, <code>StaticDisplayLevels</code>, <code>MaximumDynamicDisplayLevels</code>, <code>DisappearAfter</code>, <code>MenuItemClick</code>, <code>MenuItemDataBound</code>.</td></tr><tr><td><code>&lt;asp:MenuItem&gt;</code></td><td><code>MenuItem</code></td><td><code>Text</code>, <code>Value</code>, <code>NavigateUrl</code>, <code>Target</code>, <code>ToolTip</code>, <code>ImageUrl</code>, <code>PopOutImageUrl</code>, <code>SeparatorImageUrl</code>, <code>Enabled</code>, <code>Selectable</code>, <code>Selected</code>, <code>ChildItems</code>, <code>Depth</code>, <code>Parent</code>, <code>ValuePath</code>.</td></tr><tr><td><code>&lt;asp:TreeView&gt;</code></td><td><code>TreeViewController</code></td><td><code>ShowCheckBoxes</code>, <code>ShowLines</code>, <code>ExpandDepth</code>, <code>SelectedNodeChanged</code>, <code>TreeNodeCheckChanged</code>, <code>TreeNodeExpanded</code>, <code>TreeNodeCollapsed</code>, <code>TreeNodeDataBound</code>.</td></tr><tr><td><code>&lt;asp:TreeNode&gt;</code></td><td><code>TreeNode</code></td><td><code>Text</code>, <code>Value</code>, <code>NavigateUrl</code>, <code>Checked</code>, <code>Expanded</code>, <code>Selectable</code>, <code>ChildNodes</code>, <code>Depth</code>, <code>Parent</code>, <code>ValuePath</code>.</td></tr><tr><td><code>TreeNodeTypes</code> enum</td><td><code>TreeNodeTypes</code></td><td><code>None</code>, <code>Root</code>, <code>Parent</code>, <code>Leaf</code>, <code>All</code>.</td></tr><tr><td><code>&lt;asp:SiteMapPath&gt;</code></td><td><code>SiteMapPathController</code></td><td><code>PathSeparator</code>, <code>PathDirection</code>, <code>ParentLevelsDisplayed</code>, <code>RenderCurrentNodeAsLink</code>, <code>ItemCreated</code>, <code>ItemDataBound</code>.</td></tr><tr><td><code>SiteMapNodeItemType</code></td><td><code>SiteMapPathItemType</code></td><td><code>Root</code>, <code>Parent</code>, <code>Current</code> (no <code>PathSeparator</code> item type; separators are produced by <code>renderText</code>).</td></tr><tr><td><code>&lt;asp:SiteMapDataSource&gt;</code></td><td><code>SiteMapDataSource</code> (documented in <a href=\"https://github.com/ahsan-wolf/webforms-ts-controls/blob/main/docs/v1.0.0/sitemap-data-source.md\" target=\"_blank\" rel=\"noopener\">sitemap-data-source.md</a>)</td><td>Used as <code>dataSource</code> / <code>siteMapProvider</code>.</td></tr><tr><td><code>Control.ClientID</code> / <code>UniqueID</code> / <code>INamingContainer</code></td><td><strong>not implemented</strong> (empty <code>naming/</code> module)</td><td>See section 7.</td></tr><tr><td><code>Menu.FindItem(valuePath)</code></td><td><code>MenuController.findItem(valueOrPath)</code></td><td>Also matches <code>value</code> and <code>text</code>.</td></tr><tr><td><code>TreeView.FindNode(valuePath)</code></td><td><code>TreeViewController.findNode(valueOrPath)</code></td><td>Also matches <code>value</code> and <code>text</code>.</td></tr><tr><td><code>TreeView.CheckedNodes</code></td><td><code>TreeViewController.getCheckedNodes()</code></td><td></td></tr><tr><td><code>TreeView.ExpandAll()/CollapseAll()</code></td><td><code>expandAll()</code> / <code>collapseAll()</code></td><td>Both async.</td></tr><tr><td>Menu/TreeView postback</td><td><code>Promise</code>-based methods that emit events</td><td>No postbacks.</td></tr></tbody></table></div>\n<hr>\n"},"quick-start":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">import</span> { <span class=\"tok-t\">MenuController</span>, <span class=\"tok-t\">TreeViewController</span>, <span class=\"tok-t\">SiteMapPathController</span>, <span class=\"tok-t\">SiteMapDataSource</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n\n<span class=\"tok-k\">const</span> menu = <span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuController</span>({\n  id: <span class=\"tok-s\">&quot;mnu&quot;</span>,\n  orientation: <span class=\"tok-s\">&quot;Horizontal&quot;</span>,\n  items: [\n    { text: <span class=\"tok-s\">&quot;File&quot;</span>, childItems: [\n      { text: <span class=\"tok-s\">&quot;New&quot;</span>, value: <span class=\"tok-s\">&quot;new&quot;</span> },\n      { text: <span class=\"tok-s\">&quot;Open&quot;</span>, value: <span class=\"tok-s\">&quot;open&quot;</span>, childItems: [{ text: <span class=\"tok-s\">&quot;Recent&quot;</span>, value: <span class=\"tok-s\">&quot;recent&quot;</span> }] }\n    ] },\n    { text: <span class=\"tok-s\">&quot;Help&quot;</span>, navigateUrl: <span class=\"tok-s\">&quot;/help&quot;</span> }\n  ]\n});\nmenu.menuItemClick.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;click&quot;</span>, e.item.valuePath));\n<span class=\"tok-k\">await</span> menu.<span class=\"tok-f\">clickItem</span>(<span class=\"tok-s\">&quot;File/open&quot;</span>);           <span class=\"tok-c\">// click File/open</span>\nconsole.<span class=\"tok-f\">log</span>(menu.selectedItem?.text);        <span class=\"tok-c\">// -&gt; Open</span></code></pre></div>\n<hr>\n"},"shared-concepts":{"hierarchy-depth-parent-valuepath":"<h3 id=\"31-hierarchy-depth-parent-valuepath\">3.1 Hierarchy: <code>depth</code>, <code>parent</code>, <code>valuePath</code><a class=\"anchor\" href=\"#31-hierarchy-depth-parent-valuepath\" aria-label=\"Link to this section\">#</a></h3>\n<p>Items (<code>MenuItem</code>) and nodes (<code>TreeNode</code>) are objects that hold <code>childItems</code>/<code>childNodes</code>, plus <code>parent</code>, <code>depth</code> (root = 0) and <code>valuePath</code>. A <code>valuePath</code> is the chain of <code>value</code> fields from root to the node joined with <code>/</code> (not <code>text</code>). Root: <code>valuePath === value</code>. Child: <code>parentValuePath + &quot;/&quot; + value</code>. <code>value</code> defaults to <code>text</code>.</p>\n<p>When are these computed?</p>\n<ul><li>The constructor links <code>parent</code> for the children it creates from nested options, but leaves <code>depth = 0</code> and <code>valuePath = &quot;&quot;</code> everywhere.</li><li><code>refreshHierarchy(parent?, depth = 0)</code> recalculates <code>parent</code>, <code>depth</code>, <code>valuePath</code> recursively. It is called by the controllers' <code>setItems</code>/<code>setNodes</code> (and their constructors, when <code>items</code>/<code>nodes</code> is given) and by <code>dataBind(source?)</code> whenever data is bound.</li><li>Verified: <code>new MenuItem({text:&quot;P&quot;, childItems:[{text:&quot;Q&quot;}]})</code> has <code>childItems[0].depth === 0</code> and <code>valuePath === &quot;&quot;</code> until <code>menu.setItems([pre])</code>, after which <code>Q.depth === 1</code>, <code>Q.valuePath === &quot;P/Q&quot;</code>.</li><li>If you mutate <code>childItems</code> or <code>value</code> after binding, call <code>item.refreshHierarchy(parent, depth)</code> on the affected root (or <code>setItems</code> again) yourself.</li></ul>\n","lookup-finditem-findnode":"<h3 id=\"32-lookup-finditem--findnode\">3.2 Lookup (<code>findItem</code> / <code>findNode</code>)<a class=\"anchor\" href=\"#32-lookup-finditem--findnode\" aria-label=\"Link to this section\">#</a></h3>\n<p>Depth-first, pre-order search. A node matches if <code>valuePath</code>, <code>value</code> <strong>or</strong> <code>text</code> equals the argument; the first match wins. Values are not required to be unique, so an ambiguous argument returns the first node in pre-order (verified: a node with <code>text &quot;1&quot;</code> nested under a node with <code>value &quot;1&quot;</code> resolves to the outer node). Use the full <code>valuePath</code> when uniqueness matters. Note that the path uses <code>value</code>, not <code>text</code>: <code>&quot;File/open/recent&quot;</code> works but <code>&quot;File/Open/Recent&quot;</code> returns <code>undefined</code> when values differ from text.</p>\n","data-binding":"<h3 id=\"33-data-binding\">3.3 Data binding<a class=\"anchor\" href=\"#33-data-binding\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>dataBind(source?)</code> accepts a <code>SiteMapDataSource</code> or an array of item/node options (or pre-built <code>MenuItem</code>/<code>TreeNode</code> instances); with no argument it uses the <code>dataSource</code> option from the constructor.</p>\n<ul><li><code>SiteMapDataSource</code>: calls <code>await ds.select()</code> (honours <code>showStartingNode</code>, <code>startingNodeUrl</code>, and cancelling <code>selecting</code>), converts each <code>SiteMapNode</code> with <code>fromSiteMapNode</code>. Converted fields: <code>text = title</code>, <code>value = key ?? url ?? title</code>, <code>navigateUrl = url ?? &quot;&quot;</code>, <code>tooltip = description ?? &quot;&quot;</code>. Other flags (<code>enabled</code>, <code>selectable</code>, <code>checked</code>, ...) take defaults; <code>roles</code> are ignored.</li><li>Array: wraps plain options in <code>MenuItem</code>/<code>TreeNode</code>, keeps existing instances.</li><li>Neither source nor stored data source: does not rebind; it only re-fires <code>*DataBound</code> for existing items.</li><li>Then <code>refreshHierarchy</code> runs on each root and the <code>*DataBound</code> event fires for every item, parents before children, awaited sequentially; then (TreeView only) <code>expandDepth</code> is applied; then <code>stateChanged</code> with reason <code>&quot;dataBind&quot;</code>.</li><li>The constructor never binds; <code>dataSource</code> is stored and used when you call <code>dataBind()</code>.</li><li>Binding a <code>SiteMapDataSource</code> with <code>showStartingNode = true</code> (default) yields <strong>one root</strong> (the sitemap root) with the rest beneath it, so <code>valuePath</code>s start with the root's value (e.g. <code>home/products/widgets</code>).</li></ul>\n","events":"<h3 id=\"34-events\">3.4 Events<a class=\"anchor\" href=\"#34-events\" aria-label=\"Link to this section\">#</a></h3>\n<p>All events are <code>EventDispatcher</code> instances: <code>subscribe(handler): () =&gt; void</code> (returns an unsubscribe), <code>emit(sender, args): Promise&lt;void&gt;</code> (awaits handlers one by one), <code>clear(): void</code>. Handlers are <code>(sender, args) =&gt; void | Promise&lt;void&gt;</code>. <code>stateChanged</code> on every controller emits <code>{ reason: string }</code> after each state mutation so adapters can re-render.</p>\n","selection":"<h3 id=\"35-selection\">3.5 Selection<a class=\"anchor\" href=\"#35-selection\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li>Selection is single (one <code>selectedItem</code>/<code>selectedNode</code>). Selecting clears <code>selected</code> on every item in the tree first, then sets it on the target.</li><li>Selecting is refused (returns <code>false</code>, no event) when the target is not found or has <code>selectable === false</code>. <code>MenuController.selectItem</code> also refuses when <code>enabled === false</code>.</li><li><code>selected: true</code> in constructor options only sets the flag; it does <strong>not</strong> set <code>selectedItem</code>/<code>selectedNode</code> on the controller.</li></ul>\n<hr>\n"},"menu":{"menuitem":"<h3 id=\"41-menuitem\">4.1 <code>MenuItem</code><a class=\"anchor\" href=\"#41-menuitem\" aria-label=\"Link to this section\">#</a></h3>\n<p>ASP.NET: <code>MenuItem</code>.</p>\n<p><strong>Constructor options (<code>MenuItemOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code> (required)</td><td>-</td><td>Display text.</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td><code>text</code></td><td>Identity used in <code>valuePath</code> and lookup.</td></tr><tr><td><code>navigateUrl</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Link target (not followed by the core).</td></tr><tr><td><code>target</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Link target window.</td></tr><tr><td><code>tooltip</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>imageUrl</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>popOutImageUrl</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>separatorImageUrl</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td><code>true</code></td><td><code>false</code> items cannot be clicked or selected.</td></tr><tr><td><code>selectable</code></td><td><code>boolean</code></td><td><code>true</code></td><td><code>false</code> items can be clicked (event fires) but not selected.</td></tr><tr><td><code>selected</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Initial flag only.</td></tr><tr><td><code>childItems</code></td><td><code>MenuItemOptions[]</code></td><td>none</td><td>Nested items (built recursively; <code>parent</code> linked).</td></tr></tbody></table></div>\n<p><strong>Properties</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code>, <code>value</code>, <code>navigateUrl</code>, <code>target</code>, <code>tooltip</code>, <code>imageUrl</code>, <code>popOutImageUrl</code>, <code>separatorImageUrl</code></td><td><code>string</code></td><td>r/w</td><td>per options</td><td></td></tr><tr><td><code>enabled</code>, <code>selectable</code>, <code>selected</code></td><td><code>boolean</code></td><td>r/w</td><td><code>true</code>, <code>true</code>, <code>false</code></td><td></td></tr><tr><td><code>childItems</code></td><td><code>MenuItem[]</code></td><td>r/w</td><td><code>[]</code></td><td></td></tr><tr><td><code>depth</code></td><td><code>number</code></td><td>r/w</td><td><code>0</code></td><td>Set by <code>refreshHierarchy</code>; treat as read-only.</td></tr><tr><td><code>parent</code></td><td><code>MenuItem | undefined</code></td><td>r/w</td><td><code>undefined</code></td><td>Linked in the constructor for nested options and by <code>refreshHierarchy</code>.</td></tr><tr><td><code>valuePath</code></td><td><code>string</code></td><td>r/w</td><td><code>&quot;&quot;</code></td><td>Set by <code>refreshHierarchy</code>; see 3.1.</td></tr></tbody></table></div>\n<p><strong>Methods</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Parameters</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>refreshHierarchy(parent?: MenuItem, currentDepth = 0): void</code></td><td><code>parent</code> - parent to assign; <code>currentDepth</code> - depth of this item</td><td><code>void</code></td><td>Recomputes <code>parent</code>, <code>depth</code>, <code>valuePath</code> for this item and all descendants.</td></tr><tr><td><code>static fromSiteMapNode(node: SiteMapNode, parent?: MenuItem): MenuItem</code></td><td><code>node</code> - sitemap node; <code>parent</code> - already converted parent</td><td><code>MenuItem</code></td><td>Converts recursively (see 3.3). Sets <code>depth</code> and <code>valuePath</code> itself.</td></tr></tbody></table></div>\n<p>Events: none.</p>\n","menucontroller":"<h3 id=\"42-menucontroller\">4.2 <code>MenuController</code><a class=\"anchor\" href=\"#42-menucontroller\" aria-label=\"Link to this section\">#</a></h3>\n<p>ASP.NET: <code>Menu</code>.</p>\n<p><strong>Types</strong></p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">type</span> <span class=\"tok-t\">MenuOrientation</span> = <span class=\"tok-s\">&quot;Horizontal&quot;</span> | <span class=\"tok-s\">&quot;Vertical&quot;</span>;\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">MenuItemClickEventArgs</span> <span class=\"tok-k\">extends</span> <span class=\"tok-t\">CancelEventArgs</span> { item: <span class=\"tok-t\">MenuItem</span>; }   <span class=\"tok-c\">// cancel: boolean</span>\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">MenuItemDataBoundEventArgs</span> { item: <span class=\"tok-t\">MenuItem</span>; }</code></pre></div>\n<p><strong>Constructor options (<code>MenuOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code> (required)</td><td>-</td><td></td></tr><tr><td><code>orientation</code></td><td><code>MenuOrientation</code></td><td><code>&quot;Vertical&quot;</code></td><td>Stored; used by the adapter for layout.</td></tr><tr><td><code>staticDisplayLevels</code></td><td><code>number</code></td><td><code>1</code></td><td>Clamped to a minimum of <code>1</code> (<code>0</code> becomes <code>1</code>).</td></tr><tr><td><code>maximumDynamicDisplayLevels</code></td><td><code>number</code></td><td><code>3</code></td><td>Clamped to a minimum of <code>0</code>.</td></tr><tr><td><code>disappearAfter</code></td><td><code>number</code></td><td><code>500</code></td><td>Flyout close delay in ms; stored for adapters (the core never starts timers).</td></tr><tr><td><code>dataSource</code></td><td><code>SiteMapDataSource | (MenuItem | MenuItemOptions)[]</code></td><td><code>undefined</code></td><td>Stored; used by <code>dataBind()</code>.</td></tr><tr><td><code>items</code></td><td><code>(MenuItem | MenuItemOptions)[]</code></td><td>none</td><td>Immediately passed to <code>setItems</code>.</td></tr></tbody></table></div>\n<p><strong>Properties</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td>-</td><td></td></tr><tr><td><code>orientation</code></td><td><code>MenuOrientation</code></td><td>r/w</td><td><code>&quot;Vertical&quot;</code></td><td></td></tr><tr><td><code>staticDisplayLevels</code></td><td><code>number</code></td><td>r/w</td><td><code>1</code></td><td>Clamp applies in the constructor only; assigning later is unchecked.</td></tr><tr><td><code>maximumDynamicDisplayLevels</code></td><td><code>number</code></td><td>r/w</td><td><code>3</code></td><td>Same note.</td></tr><tr><td><code>disappearAfter</code></td><td><code>number</code></td><td>r/w</td><td><code>500</code></td><td></td></tr><tr><td><code>items</code></td><td><code>MenuItem[]</code></td><td>r/w</td><td><code>[]</code></td><td>Root items.</td></tr><tr><td><code>selectedItem</code></td><td><code>MenuItem | undefined</code></td><td>r/w</td><td><code>undefined</code></td><td>Set by <code>selectItem</code>/<code>clickItem</code>.</td></tr><tr><td><code>menuItemClick</code></td><td><code>EventDispatcher&lt;this, MenuItemClickEventArgs&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr><tr><td><code>menuItemDataBound</code></td><td><code>EventDispatcher&lt;this, MenuItemDataBoundEventArgs&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr><tr><td><code>stateChanged</code></td><td><code>EventDispatcher&lt;this, { reason: string }&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr></tbody></table></div>\n<p><strong>Methods</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Parameters</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>setItems(rawItems: (MenuItem | MenuItemOptions)[]): void</code></td><td><code>rawItems</code> - roots; instances are kept as-is</td><td><code>void</code></td><td>-</td><td>Replaces <code>items</code>, runs <code>refreshHierarchy</code> on each root. Does not emit events.</td></tr><tr><td><code>dataBind(source?: SiteMapDataSource | (MenuItem | MenuItemOptions)[]): Promise&lt;void&gt;</code></td><td><code>source</code> - overrides the constructor <code>dataSource</code></td><td>resolves when done</td><td>errors from <code>ds.select()</code> or handlers</td><td>See 3.3. Emits <code>menuItemDataBound</code> per item then <code>stateChanged(&quot;dataBind&quot;)</code>.</td></tr><tr><td><code>getStaticItems(): MenuItem[]</code></td><td>-</td><td>Items with <code>depth &lt; staticDisplayLevels</code>, pre-order, flattened</td><td>-</td><td>The always-visible items.</td></tr><tr><td><code>getDynamicItems(parentItem: MenuItem): MenuItem[]</code></td><td><code>parentItem</code> - item whose flyout you want</td><td>Children with <code>depth &lt;= staticDisplayLevels + maximumDynamicDisplayLevels</code></td><td>-</td><td>Returns <code>[]</code> while <code>parentItem.depth &lt; staticDisplayLevels - 1</code> (children are still static).</td></tr><tr><td><code>findItem(valueOrPath: string): MenuItem | undefined</code></td><td><code>valueOrPath</code> - <code>valuePath</code>, <code>value</code>, or <code>text</code></td><td>first match</td><td>-</td><td>See 3.2.</td></tr><tr><td><code>selectItem(itemOrValue: MenuItem | string): Promise&lt;boolean&gt;</code></td><td>an item or a lookup string</td><td><code>true</code> if selected</td><td>-</td><td>Refuses (<code>false</code>) if missing, disabled or not selectable. Clears prior selection, sets <code>selectedItem</code>, emits <code>stateChanged(&quot;selectItem&quot;)</code>.</td></tr><tr><td><code>clickItem(itemOrValue: MenuItem | string): Promise&lt;boolean&gt;</code></td><td>an item or a lookup string</td><td><code>true</code> if the click was not cancelled</td><td>-</td><td>Refuses (<code>false</code>) if missing or disabled. Emits <code>menuItemClick</code> (cancellable). If cancelled returns <code>false</code> and nothing else happens. Otherwise selects the item (only if <code>selectable</code>) and returns <code>true</code>, even when it was not selectable.</td></tr></tbody></table></div>\n<p><strong>Events</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Event</th><th>Args</th><th>Cancellable</th><th>Raised</th></tr></thead><tbody><tr><td><code>menuItemClick</code></td><td><code>{ item, cancel }</code></td><td>Yes (<code>e.cancel = true</code>)</td><td>From <code>clickItem</code>, before selection.</td></tr><tr><td><code>menuItemDataBound</code></td><td><code>{ item }</code></td><td>No</td><td><code>dataBind</code>, once per item, parents first.</td></tr><tr><td><code>stateChanged</code></td><td><code>{ reason }</code></td><td>No</td><td>Reasons: <code>&quot;dataBind&quot;</code>, <code>&quot;selectItem&quot;</code>.</td></tr></tbody></table></div>\n<p><strong>Flyout / expand state.</strong> The menu has no <code>expanded</code> flag. Static vs dynamic is purely computed from <code>depth</code>:</p>\n<ul><li>Items with <code>depth &lt; staticDisplayLevels</code> are static (always shown).</li><li>Flyouts (dynamic items) show for an item at depth <code>&gt;= staticDisplayLevels - 1</code>, limited to children whose depth is <code>&lt;= staticDisplayLevels + maximumDynamicDisplayLevels</code>.</li><li>Verified with <code>staticDisplayLevels: 2, maximumDynamicDisplayLevels: 1</code> over A &gt; B &gt; C &gt; D &gt; E: static <code>[A, B]</code>; dynamic of A is <code>[]</code>, of B <code>[C]</code>, of C <code>[D]</code>, of D <code>[]</code>.</li><li>Hover/open timing (<code>disappearAfter</code>) is an adapter concern; the core keeps no &quot;open flyout&quot; state.</li></ul>\n<hr>\n"},"treeview":{"treenode":"<h3 id=\"51-treenode\">5.1 <code>TreeNode</code><a class=\"anchor\" href=\"#51-treenode\" aria-label=\"Link to this section\">#</a></h3>\n<p>ASP.NET: <code>TreeNode</code>.</p>\n<p><strong>Constructor options (<code>TreeNodeOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code> (required)</td><td>-</td><td></td></tr><tr><td><code>value</code></td><td><code>string</code></td><td><code>text</code></td><td></td></tr><tr><td><code>navigateUrl</code>, <code>target</code>, <code>tooltip</code>, <code>imageUrl</code>, <code>expandedImageUrl</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td></td></tr><tr><td><code>checked</code></td><td><code>boolean</code></td><td><code>false</code></td><td></td></tr><tr><td><code>expanded</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Overridden by <code>expandDepth</code> when binding a tree (see 5.2).</td></tr><tr><td><code>selectable</code></td><td><code>boolean</code></td><td><code>true</code></td><td></td></tr><tr><td><code>selected</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Initial flag only.</td></tr><tr><td><code>childNodes</code></td><td><code>TreeNodeOptions[]</code></td><td>none</td><td>Nested nodes.</td></tr></tbody></table></div>\n<p><strong>Properties</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code>, <code>value</code>, <code>navigateUrl</code>, <code>target</code>, <code>tooltip</code>, <code>imageUrl</code>, <code>expandedImageUrl</code></td><td><code>string</code></td><td>r/w</td><td>per options</td><td></td></tr><tr><td><code>checked</code>, <code>expanded</code>, <code>selectable</code>, <code>selected</code></td><td><code>boolean</code></td><td>r/w</td><td><code>false</code>, <code>false</code>, <code>true</code>, <code>false</code></td><td></td></tr><tr><td><code>childNodes</code></td><td><code>TreeNode[]</code></td><td>r/w</td><td><code>[]</code></td><td></td></tr><tr><td><code>depth</code></td><td><code>number</code></td><td>r/w</td><td><code>0</code></td><td>Set by <code>refreshHierarchy</code>.</td></tr><tr><td><code>parent</code></td><td><code>TreeNode | undefined</code></td><td>r/w</td><td><code>undefined</code></td><td></td></tr><tr><td><code>valuePath</code></td><td><code>string</code></td><td>r/w</td><td><code>&quot;&quot;</code></td><td>See 3.1.</td></tr><tr><td><code>isLeaf</code></td><td><code>boolean</code></td><td>r (getter)</td><td>-</td><td><code>childNodes.length === 0</code>.</td></tr><tr><td><code>isRoot</code></td><td><code>boolean</code></td><td>r (getter)</td><td>-</td><td><code>!parent</code>. Becomes <code>true</code> for any detached node.</td></tr></tbody></table></div>\n<p><strong>Methods</strong>: <code>refreshHierarchy(parent?: TreeNode, currentDepth = 0): void</code> and <code>static fromSiteMapNode(node: SiteMapNode, parent?: TreeNode): TreeNode</code> - same behaviour as <code>MenuItem</code> (section 4.1).</p>\n<p>Events: none.</p>\n","treeviewcontroller":"<h3 id=\"52-treeviewcontroller\">5.2 <code>TreeViewController</code><a class=\"anchor\" href=\"#52-treeviewcontroller\" aria-label=\"Link to this section\">#</a></h3>\n<p>ASP.NET: <code>TreeView</code>.</p>\n<p><strong>Types</strong></p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">type</span> <span class=\"tok-t\">TreeNodeTypes</span> = <span class=\"tok-s\">&quot;None&quot;</span> | <span class=\"tok-s\">&quot;Root&quot;</span> | <span class=\"tok-s\">&quot;Parent&quot;</span> | <span class=\"tok-s\">&quot;Leaf&quot;</span> | <span class=\"tok-s\">&quot;All&quot;</span>;\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">TreeNodeEventArgs</span> { node: <span class=\"tok-t\">TreeNode</span>; }\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">TreeNodeCheckEventArgs</span> { node: <span class=\"tok-t\">TreeNode</span>; checked: boolean; }</code></pre></div>\n<p><strong>Constructor options (<code>TreeViewOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code> (required)</td><td>-</td><td></td></tr><tr><td><code>showCheckBoxes</code></td><td><code>TreeNodeTypes</code></td><td><code>&quot;None&quot;</code></td><td>Which nodes get a checkbox (see <code>shouldShowCheckBox</code>).</td></tr><tr><td><code>showLines</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Stored for adapters.</td></tr><tr><td><code>expandDepth</code></td><td><code>number</code></td><td><code>-1</code></td><td><code>-1</code> leaves each node's own <code>expanded</code> untouched. <code>&gt;= 0</code> forces <code>expanded = depth &lt; expandDepth</code> on every node during <code>setNodes</code>/<code>dataBind</code>. <code>0</code> collapses everything.</td></tr><tr><td><code>dataSource</code></td><td><code>SiteMapDataSource | (TreeNode | TreeNodeOptions)[]</code></td><td><code>undefined</code></td><td>Stored; used by <code>dataBind()</code>.</td></tr><tr><td><code>nodes</code></td><td><code>(TreeNode | TreeNodeOptions)[]</code></td><td>none</td><td>Passed to <code>setNodes</code> immediately.</td></tr></tbody></table></div>\n<p><strong>Properties</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>r</td><td>-</td><td></td></tr><tr><td><code>showCheckBoxes</code></td><td><code>TreeNodeTypes</code></td><td>r/w</td><td><code>&quot;None&quot;</code></td><td></td></tr><tr><td><code>showLines</code></td><td><code>boolean</code></td><td>r/w</td><td><code>false</code></td><td></td></tr><tr><td><code>expandDepth</code></td><td><code>number</code></td><td>r/w</td><td><code>-1</code></td><td>Read at the next <code>setNodes</code>/<code>dataBind</code>.</td></tr><tr><td><code>nodes</code></td><td><code>TreeNode[]</code></td><td>r/w</td><td><code>[]</code></td><td>Root nodes.</td></tr><tr><td><code>selectedNode</code></td><td><code>TreeNode | undefined</code></td><td>r/w</td><td><code>undefined</code></td><td></td></tr><tr><td><code>selectedNodeChanged</code></td><td><code>EventDispatcher&lt;this, TreeNodeEventArgs&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr><tr><td><code>treeNodeCheckChanged</code></td><td><code>EventDispatcher&lt;this, TreeNodeCheckEventArgs&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr><tr><td><code>treeNodeExpanded</code></td><td><code>EventDispatcher&lt;this, TreeNodeEventArgs&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr><tr><td><code>treeNodeCollapsed</code></td><td><code>EventDispatcher&lt;this, TreeNodeEventArgs&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr><tr><td><code>treeNodeDataBound</code></td><td><code>EventDispatcher&lt;this, TreeNodeEventArgs&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr><tr><td><code>stateChanged</code></td><td><code>EventDispatcher&lt;this, { reason: string }&gt;</code></td><td>r</td><td>-</td><td>Event.</td></tr></tbody></table></div>\n<p><strong>Methods</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Parameters</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>setNodes(rawNodes: (TreeNode | TreeNodeOptions)[]): void</code></td><td>roots</td><td><code>void</code></td><td>Replaces <code>nodes</code>, refreshes hierarchy, applies <code>expandDepth</code> if <code>&gt;= 0</code>. No events.</td></tr><tr><td><code>dataBind(source?: SiteMapDataSource | (TreeNode | TreeNodeOptions)[]): Promise&lt;void&gt;</code></td><td>optional override source</td><td>resolves</td><td>See 3.3. Emits <code>treeNodeDataBound</code> per node, applies <code>expandDepth</code>, emits <code>stateChanged(&quot;dataBind&quot;)</code>.</td></tr><tr><td><code>shouldShowCheckBox(node: TreeNode): boolean</code></td><td>node</td><td><code>boolean</code></td><td><code>All</code>: true; <code>Root</code>: <code>node.isRoot</code>; <code>Parent</code>: <code>!node.isLeaf</code>; <code>Leaf</code>: <code>node.isLeaf</code>; <code>None</code>: false. Note <code>Parent</code> means &quot;has children&quot; (a root with children qualifies; the check is not &quot;non-root with children&quot;).</td></tr><tr><td><code>findNode(valueOrPath: string): TreeNode | undefined</code></td><td><code>valuePath</code>, <code>value</code>, or <code>text</code></td><td>first match (pre-order)</td><td>See 3.2.</td></tr><tr><td><code>selectNode(nodeOrValue: TreeNode | string): Promise&lt;boolean&gt;</code></td><td></td><td><code>true</code> if selected</td><td>Refuses if missing or <code>selectable === false</code>. Clears all <code>selected</code>, sets <code>selectedNode</code>, emits <code>selectedNodeChanged</code> then <code>stateChanged(&quot;selectNode&quot;)</code>. Always emits even if the node was already selected.</td></tr><tr><td><code>checkNode(nodeOrValue: TreeNode | string, checked: boolean): Promise&lt;boolean&gt;</code></td><td>node, desired state</td><td><code>false</code> if node missing</td><td>Sets <code>node.checked</code>, emits <code>treeNodeCheckChanged</code> then <code>stateChanged(&quot;checkNode&quot;)</code>. Does <strong>not</strong> check <code>shouldShowCheckBox</code>, <code>enabled</code>, or no-op detection (fires even if unchanged).</td></tr><tr><td><code>expandNode(nodeOrValue): Promise&lt;boolean&gt;</code></td><td></td><td><code>false</code> if missing or already expanded</td><td>Sets <code>expanded = true</code>, emits <code>treeNodeExpanded</code>, <code>stateChanged(&quot;expandNode&quot;)</code>.</td></tr><tr><td><code>collapseNode(nodeOrValue): Promise&lt;boolean&gt;</code></td><td></td><td><code>false</code> if missing or already collapsed</td><td>Emits <code>treeNodeCollapsed</code>, <code>stateChanged(&quot;collapseNode&quot;)</code>.</td></tr><tr><td><code>toggleNode(nodeOrValue): Promise&lt;boolean&gt;</code></td><td></td><td><code>false</code> if missing</td><td>Collapses if expanded, else expands.</td></tr><tr><td><code>expandAll(): Promise&lt;void&gt;</code></td><td>-</td><td>-</td><td>Sets <code>expanded = true</code> everywhere. Emits only <code>stateChanged(&quot;expandAll&quot;)</code> (no per-node events).</td></tr><tr><td><code>collapseAll(): Promise&lt;void&gt;</code></td><td>-</td><td>-</td><td>Same, <code>stateChanged(&quot;collapseAll&quot;)</code>.</td></tr><tr><td><code>expandToDepth(depth: number): Promise&lt;void&gt;</code></td><td><code>depth</code> - nodes with <code>node.depth &lt; depth</code> expand, others collapse</td><td>-</td><td>Emits <code>stateChanged(&quot;expandToDepth&quot;)</code> only.</td></tr><tr><td><code>getCheckedNodes(): TreeNode[]</code></td><td>-</td><td>Pre-order flat list of nodes with <code>checked === true</code></td><td>Includes nodes without a visible checkbox.</td></tr></tbody></table></div>\n<p><strong>Events</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Event</th><th>Args</th><th>Cancellable</th><th>Raised</th></tr></thead><tbody><tr><td><code>selectedNodeChanged</code></td><td><code>{ node }</code></td><td>No</td><td><code>selectNode</code> success.</td></tr><tr><td><code>treeNodeCheckChanged</code></td><td><code>{ node, checked }</code></td><td>No</td><td><code>checkNode</code>.</td></tr><tr><td><code>treeNodeExpanded</code></td><td><code>{ node }</code></td><td>No</td><td><code>expandNode</code> / <code>toggleNode</code> that expanded.</td></tr><tr><td><code>treeNodeCollapsed</code></td><td><code>{ node }</code></td><td>No</td><td><code>collapseNode</code> / <code>toggleNode</code> that collapsed.</td></tr><tr><td><code>treeNodeDataBound</code></td><td><code>{ node }</code></td><td>No</td><td><code>dataBind</code>, once per node, parents first.</td></tr><tr><td><code>stateChanged</code></td><td><code>{ reason }</code></td><td>No</td><td>Reasons: <code>dataBind</code>, <code>selectNode</code>, <code>checkNode</code>, <code>expandNode</code>, <code>collapseNode</code>, <code>expandAll</code>, <code>collapseAll</code>, <code>expandToDepth</code>.</td></tr></tbody></table></div>\n<p><strong>Checkbox propagation: not built in.</strong> Unlike a Web Forms tri-state tree, the controller never propagates checks to children or parents. <code>checkNode</code> changes exactly one node. Implement propagation in a <code>treeNodeCheckChanged</code> handler (example 5); because the handler mutates <code>.checked</code> directly it does not re-fire the event, but guard re-entrancy if you call <code>checkNode</code> inside it.</p>\n<hr>\n"},"sitemappath":{"overview":"<p>ASP.NET: <code>SiteMapPath</code>. Builds breadcrumb items from a <code>SiteMapDataSource</code>.</p>\n<p><strong>Types</strong></p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">type</span> <span class=\"tok-t\">PathDirection</span> = <span class=\"tok-s\">&quot;RootToCurrent&quot;</span> | <span class=\"tok-s\">&quot;CurrentToRoot&quot;</span>;\n<span class=\"tok-k\">type</span> <span class=\"tok-t\">SiteMapPathItemType</span> = <span class=\"tok-s\">&quot;Root&quot;</span> | <span class=\"tok-s\">&quot;Parent&quot;</span> | <span class=\"tok-s\">&quot;Current&quot;</span>;\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">SiteMapPathItem</span> {\n  itemType: <span class=\"tok-t\">SiteMapPathItemType</span>;\n  node: <span class=\"tok-t\">SiteMapNode</span>;     <span class=\"tok-c\">// the underlying site map node</span>\n  text: string;          <span class=\"tok-c\">// node.title</span>\n  url: string;           <span class=\"tok-c\">// node.url ?? &quot;&quot;</span>\n  isLink: boolean;\n}</code></pre></div>\n<p><strong>Constructor options (<code>SiteMapPathOptions</code>)</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code> (required)</td><td>-</td><td></td></tr><tr><td><code>siteMapProvider</code></td><td><code>SiteMapDataSource</code></td><td><code>undefined</code></td><td>Source of the hierarchy.</td></tr><tr><td><code>pathSeparator</code></td><td><code>string</code></td><td><code>&quot; &gt; &quot;</code></td><td>Used by <code>renderText</code>.</td></tr><tr><td><code>pathDirection</code></td><td><code>PathDirection</code></td><td><code>&quot;RootToCurrent&quot;</code></td><td></td></tr><tr><td><code>parentLevelsDisplayed</code></td><td><code>number</code></td><td><code>-1</code></td><td><code>-1</code> = all parents. <code>&gt;= 0</code> = keep only that many parents nearest to the current node (root and current are always kept).</td></tr><tr><td><code>showToolTips</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Stored for adapters.</td></tr><tr><td><code>renderCurrentNodeAsLink</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Controls <code>isLink</code> for the <code>Current</code> item.</td></tr><tr><td><code>currentUrlOrKey</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Node identity (matches <code>SiteMapNode.url</code> or <code>.key</code>).</td></tr></tbody></table></div>\n<p><strong>Properties</strong>: <code>id</code> (r), <code>siteMapProvider</code>, <code>pathSeparator</code>, <code>pathDirection</code>, <code>parentLevelsDisplayed</code>, <code>showToolTips</code>, <code>renderCurrentNodeAsLink</code>, <code>currentUrlOrKey</code> (all r/w, defaults above), and events <code>itemCreated</code>, <code>itemDataBound</code> (<code>EventDispatcher&lt;this, { item: SiteMapPathItem }&gt;</code>) and <code>stateChanged</code> (<code>{ reason }</code>).</p>\n<p><strong>Methods</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Parameters</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>getItems(): SiteMapPathItem[]</code></td><td>-</td><td>A copy of the current items</td><td>Empty before the first <code>dataBind</code>.</td></tr><tr><td><code>dataBind(currentUrlOrKey?: string): Promise&lt;SiteMapPathItem[]&gt;</code></td><td>override for the current location</td><td>The new items (the internal array itself, not a copy)</td><td>Path generation below. Emits per-item events then <code>stateChanged(&quot;dataBind&quot;)</code>.</td></tr><tr><td><code>renderText(): string</code></td><td>-</td><td><code>items.map(text).join(pathSeparator)</code></td><td>Plain text; follows <code>pathDirection</code> as already applied.</td></tr></tbody></table></div>\n<p><strong>Path generation algorithm</strong></p>\n<ol><li><code>key = argument ?? this.currentUrlOrKey</code>. If there is no provider or no key: items cleared, <code>stateChanged(&quot;dataBind&quot;)</code>, return <code>[]</code>.</li><li>Store <code>currentUrlOrKey = key</code> (even if it turns out to be unknown).</li><li><code>provider.getBreadcrumbs(key)</code> finds the first node whose <code>key</code> or <code>url</code> equals it (depth-first) and walks <code>parent</code> links, returning <code>[root, ..., current]</code>. No match -&gt; <code>[]</code> -&gt; items cleared, event, return <code>[]</code>.</li><li>If <code>parentLevelsDisplayed &gt;= 0</code> and the path has more than 2 nodes: keep <code>root</code>, the last <code>parentLevelsDisplayed</code> intermediates, and <code>current</code>.</li><li>Item types: first is <code>Root</code>, last is <code>Current</code>, the rest <code>Parent</code>. A single-node path yields just <code>Current</code> (the <code>Current</code> assignment overrides <code>Root</code>).</li><li><code>isLink</code>: for <code>Current</code> it is <code>renderCurrentNodeAsLink</code>; otherwise <code>Boolean(node.url)</code> (a parent with no URL is plain text).</li><li>For each item: <code>itemCreated</code> then <code>itemDataBound</code> (both before the item is stored; both carry the same object and may mutate it).</li><li>If <code>pathDirection === &quot;CurrentToRoot&quot;</code> the list is reversed (events fire in root-to-current order regardless). <code>item.itemType</code> is not changed by reversing.</li></ol>\n<p><strong>Events</strong></p>\n<div class=\"table-scroll\"><table><thead><tr><th>Event</th><th>Args</th><th>Cancellable</th><th>Raised</th></tr></thead><tbody><tr><td><code>itemCreated</code></td><td><code>{ item }</code></td><td>No</td><td>Per item during <code>dataBind</code>, before <code>itemDataBound</code>.</td></tr><tr><td><code>itemDataBound</code></td><td><code>{ item }</code></td><td>No</td><td>Per item during <code>dataBind</code>.</td></tr><tr><td><code>stateChanged</code></td><td><code>{ reason: &quot;dataBind&quot; }</code></td><td>No</td><td>End of every <code>dataBind</code>, including empty results.</td></tr></tbody></table></div>\n<p>Gotcha: the <code>parent</code> links are created by <code>SiteMapDataSource</code> when it is constructed with <code>siteMap</code>; if you assign <code>siteMap</code> later, the links are missing and breadcrumbs will contain only the matched node.</p>\n<hr>\n"},"namingcontainer-and-clientid-uniqueid":{"what-exists":"<h3 id=\"71-what-exists\">7.1 What exists<a class=\"anchor\" href=\"#71-what-exists\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>File</th><th>State</th></tr></thead><tbody><tr><td><code>packages/core/src/naming/index.ts</code></td><td>empty (0 bytes)</td></tr><tr><td><code>packages/core/src/naming/naming-container.ts</code></td><td>empty (0 bytes)</td></tr><tr><td><code>packages/core/dist/naming/*.js</code></td><td>emits only <code>&quot;use strict&quot;;</code>; <code>.d.ts</code> files are empty</td></tr><tr><td><code>packages/core/test/naming.test.mjs</code></td><td>empty (0 bytes)</td></tr><tr><td><code>packages/core/src/index.ts</code></td><td>does <strong>not</strong> <code>export * from &quot;./naming/index.js&quot;</code></td></tr></tbody></table></div>\n<p>Verified at runtime:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">javascript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-javascript\"><span class=\"tok-k\">import</span> * <span class=\"tok-k\">as</span> <span class=\"tok-t\">C</span> <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;NamingContainer&quot;</span> <span class=\"tok-k\">in</span> <span class=\"tok-t\">C</span>, <span class=\"tok-t\">Object</span>.<span class=\"tok-f\">keys</span>(<span class=\"tok-t\">C</span>).<span class=\"tok-f\">filter</span>(k =&gt; /naming|clientid|uniqueid/i.<span class=\"tok-f\">test</span>(k)));\n<span class=\"tok-c\">// -&gt; false []</span></code></pre></div>\n<p>No class, function, type, <code>ClientID</code>, <code>UniqueID</code>, <code>ClientIDMode</code>, or &quot;collision-free key&quot; API is available, so no composition rules can be documented. The commit that created the folder (<code>d03e63b</code>) also touched React/Angular <code>dist</code> output, but no source for the naming feature is present in <code>packages/core/src</code>.</p>\n","what-identifies-things-today":"<h3 id=\"72-what-identifies-things-today\">7.2 What identifies things today<a class=\"anchor\" href=\"#72-what-identifies-things-today\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li>Every controller takes a required <code>id: string</code> (<code>readonly</code>), used as-is. Composition is entirely up to the caller; the core never prefixes or deduplicates ids.</li><li>Validators are looked up by <code>controlToValidate</code> strings through <code>ValidatorManager</code> and never validate id uniqueness (two controls with the same id share an accessor entry; the later <code>registerValueAccessor</code> replaces the earlier).</li><li>Hierarchical identity inside navigation controls is provided by <code>valuePath</code> (section 3.1): the <code>/</code>-joined chain of <code>value</code>s. It is unique only if sibling <code>value</code>s are unique.</li></ul>\n<p>If you need Web Forms style <code>UniqueID</code>/<code>ClientID</code> composition, build the id yourself, for example <code>parentId + &quot;$&quot; + childId</code> (UniqueID) and <code>parentId + &quot;_&quot; + childId</code> (ClientID) as a naming convention in your own code, and pass the result as <code>id</code>. This is a usage suggestion, not a feature of the library.</p>\n<hr>\n"},"examples":{"examples":"<p>Run as ES modules; <code>SiteMapDataSource</code> used in the examples:</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> sm = () =&gt; <span class=\"tok-k\">new</span> <span class=\"tok-t\">SiteMapDataSource</span>({ id: <span class=\"tok-s\">&quot;sm&quot;</span>, siteMap: {\n  key: <span class=\"tok-s\">&quot;home&quot;</span>, url: <span class=\"tok-s\">&quot;/&quot;</span>, title: <span class=\"tok-s\">&quot;Home&quot;</span>, description: <span class=\"tok-s\">&quot;Start&quot;</span>, childNodes: [\n    { key: <span class=\"tok-s\">&quot;products&quot;</span>, url: <span class=\"tok-s\">&quot;/products&quot;</span>, title: <span class=\"tok-s\">&quot;Products&quot;</span>, childNodes: [\n      { key: <span class=\"tok-s\">&quot;widgets&quot;</span>, url: <span class=\"tok-s\">&quot;/products/widgets&quot;</span>, title: <span class=\"tok-s\">&quot;Widgets&quot;</span>, description: <span class=\"tok-s\">&quot;All widgets&quot;</span>,\n        childNodes: [{ key: <span class=\"tok-s\">&quot;blue&quot;</span>, url: <span class=\"tok-s\">&quot;/products/widgets/blue&quot;</span>, title: <span class=\"tok-s\">&quot;Blue Widget&quot;</span> }] },\n      { key: <span class=\"tok-s\">&quot;gadgets&quot;</span>, url: <span class=\"tok-s\">&quot;/products/gadgets&quot;</span>, title: <span class=\"tok-s\">&quot;Gadgets&quot;</span> } ] },\n    { key: <span class=\"tok-s\">&quot;about&quot;</span>, title: <span class=\"tok-s\">&quot;About&quot;</span> } ] } });</code></pre></div>\n<ul class=\"aa-doc-index\"><li><a href=\"#/api/navigation/examples/examples/example-1---menu-from-nested-items-with-select-and-click-events\">Example 1 - Menu from nested items with select and click events</a></li><li><a href=\"#/api/navigation/examples/examples/example-2---static-levels-and-flyouts\">Example 2 - Static levels and flyouts</a></li><li><a href=\"#/api/navigation/examples/examples/example-3---menu-from-a-sitemapdatasource\">Example 3 - Menu from a SiteMapDataSource</a></li><li><a href=\"#/api/navigation/examples/examples/example-4---tree-checkbox-visibility-by-showcheckboxes\">Example 4 - Tree checkbox visibility by showCheckBoxes</a></li><li><a href=\"#/api/navigation/examples/examples/example-5---tree-with-check-propagation-down-and-up-implemented-in-a-handler\">Example 5 - Tree with check propagation (down and up) implemented in a handler</a></li><li><a href=\"#/api/navigation/examples/examples/example-6---expandcollapseselect-events-with-a-sitemap-bound-tree\">Example 6 - Expand/collapse/select events with a SiteMap-bound tree</a></li><li><a href=\"#/api/navigation/examples/examples/example-7---breadcrumb-from-a-site-map\">Example 7 - Breadcrumb from a site map</a></li><li><a href=\"#/api/navigation/examples/examples/example-8---limiting-parent-levels-current-as-link-unknown-keys\">Example 8 - Limiting parent levels, current-as-link, unknown keys</a></li><li><a href=\"#/api/navigation/examples/examples/example-9---mutating-a-node-after-binding-refresh-the-hierarchy\">Example 9 - Mutating a node after binding (refresh the hierarchy)</a></li><li><a href=\"#/api/navigation/examples/examples/example-10---distinct-ids-without-namingcontainer\">Example 10 - Distinct ids without NamingContainer</a></li></ul><h3 id=\"example-1---menu-from-nested-items-with-select-and-click-events\">Example 1 - Menu from nested items with select and click events<a class=\"anchor\" href=\"#example-1---menu-from-nested-items-with-select-and-click-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> menu = <span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuController</span>({ id: <span class=\"tok-s\">&quot;mnu&quot;</span>, orientation: <span class=\"tok-s\">&quot;Horizontal&quot;</span>, items: [\n  { text: <span class=\"tok-s\">&quot;File&quot;</span>, childItems: [\n    { text: <span class=\"tok-s\">&quot;New&quot;</span>, value: <span class=\"tok-s\">&quot;new&quot;</span> },\n    { text: <span class=\"tok-s\">&quot;Open&quot;</span>, value: <span class=\"tok-s\">&quot;open&quot;</span>, childItems: [{ text: <span class=\"tok-s\">&quot;Recent&quot;</span>, value: <span class=\"tok-s\">&quot;recent&quot;</span> }] },\n    { text: <span class=\"tok-s\">&quot;Exit&quot;</span>, value: <span class=\"tok-s\">&quot;exit&quot;</span>, enabled: <span class=\"tok-k\">false</span> } ] },\n  { text: <span class=\"tok-s\">&quot;Help&quot;</span>, selectable: <span class=\"tok-k\">false</span>, navigateUrl: <span class=\"tok-s\">&quot;/help&quot;</span> } ] });\n\nmenu.items.<span class=\"tok-f\">map</span>(i =&gt; [i.text, i.value, i.depth, i.valuePath]);\n<span class=\"tok-c\">// -&gt; [ [ 'File', 'File', 0, 'File' ], [ 'Help', 'Help', 0, 'Help' ] ]</span>\n<span class=\"tok-k\">const</span> recent = menu.<span class=\"tok-f\">findItem</span>(<span class=\"tok-s\">&quot;File/open/recent&quot;</span>);\nconsole.<span class=\"tok-f\">log</span>(recent.text, recent.valuePath, recent.depth, recent.parent.text);\n<span class=\"tok-c\">// -&gt; Recent File/open/recent 2 Open</span>\nmenu.<span class=\"tok-f\">findItem</span>(<span class=\"tok-s\">&quot;File/Open/Recent&quot;</span>);   <span class=\"tok-c\">// -&gt; undefined  (path uses values, not text)</span>\n\nmenu.menuItemClick.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; { console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;click&quot;</span>, e.item.valuePath); <span class=\"tok-k\">if</span> (e.item.value === <span class=\"tok-s\">&quot;new&quot;</span>) e.cancel = <span class=\"tok-k\">true</span>; });\nmenu.stateChanged.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;state&quot;</span>, e.reason));\n\n<span class=\"tok-k\">await</span> menu.<span class=\"tok-f\">clickItem</span>(<span class=\"tok-s\">&quot;File/open&quot;</span>);   <span class=\"tok-c\">// click File/open / state selectItem   -&gt; true, selectedItem &quot;Open&quot;</span>\n<span class=\"tok-k\">await</span> menu.<span class=\"tok-f\">clickItem</span>(<span class=\"tok-s\">&quot;new&quot;</span>);         <span class=\"tok-c\">// click File/new                       -&gt; false (cancelled; selection stays &quot;Open&quot;)</span>\n<span class=\"tok-k\">await</span> menu.<span class=\"tok-f\">clickItem</span>(<span class=\"tok-s\">&quot;exit&quot;</span>);        <span class=\"tok-c\">// -&gt; false  (disabled: no event at all)</span>\n<span class=\"tok-k\">await</span> menu.<span class=\"tok-f\">clickItem</span>(<span class=\"tok-s\">&quot;Help&quot;</span>);        <span class=\"tok-c\">// click Help  -&gt; true, but not selected (selectable:false); selectedItem stays &quot;Open&quot;</span>\n<span class=\"tok-k\">await</span> menu.<span class=\"tok-f\">selectItem</span>(<span class=\"tok-s\">&quot;Help&quot;</span>);       <span class=\"tok-c\">// -&gt; false</span></code></pre></div>\n<h3 id=\"example-2---static-levels-and-flyouts\">Example 2 - Static levels and flyouts<a class=\"anchor\" href=\"#example-2---static-levels-and-flyouts\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\">menu.<span class=\"tok-f\">getStaticItems</span>().<span class=\"tok-f\">map</span>(i =&gt; i.text);                           <span class=\"tok-c\">// -&gt; [ 'File', 'Help' ]</span>\nmenu.<span class=\"tok-f\">getDynamicItems</span>(menu.<span class=\"tok-f\">findItem</span>(<span class=\"tok-s\">&quot;File&quot;</span>)).<span class=\"tok-f\">map</span>(i =&gt; i.text);     <span class=\"tok-c\">// -&gt; [ 'New', 'Open', 'Exit' ]</span>\nmenu.<span class=\"tok-f\">getDynamicItems</span>(menu.<span class=\"tok-f\">findItem</span>(<span class=\"tok-s\">&quot;open&quot;</span>)).<span class=\"tok-f\">map</span>(i =&gt; i.text);     <span class=\"tok-c\">// -&gt; [ 'Recent' ]</span>\n\n<span class=\"tok-k\">const</span> m2 = <span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuController</span>({ id: <span class=\"tok-s\">&quot;m2&quot;</span>, staticDisplayLevels: <span class=\"tok-n\">2</span>, maximumDynamicDisplayLevels: <span class=\"tok-n\">1</span>,\n  items: [{ text: <span class=\"tok-s\">&quot;A&quot;</span>, childItems: [{ text: <span class=\"tok-s\">&quot;B&quot;</span>, childItems: [{ text: <span class=\"tok-s\">&quot;C&quot;</span>, childItems: [{ text: <span class=\"tok-s\">&quot;D&quot;</span>, childItems: [{ text: <span class=\"tok-s\">&quot;E&quot;</span> }] }] }] }] }] });\nm2.<span class=\"tok-f\">getStaticItems</span>().<span class=\"tok-f\">map</span>(i =&gt; i.text);                             <span class=\"tok-c\">// -&gt; [ 'A', 'B' ]</span>\n<span class=\"tok-c\">// dynamic of A -&gt; []   of B -&gt; [ 'C' ]   of C -&gt; [ 'D' ]   of D -&gt; []</span>\n\n<span class=\"tok-k\">const</span> m3 = <span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuController</span>({ id: <span class=\"tok-s\">&quot;m3&quot;</span>, staticDisplayLevels: <span class=\"tok-n\">0</span>, maximumDynamicDisplayLevels: -<span class=\"tok-n\">5</span> });\nconsole.<span class=\"tok-f\">log</span>(m3.staticDisplayLevels, m3.maximumDynamicDisplayLevels);  <span class=\"tok-c\">// -&gt; 1 0</span></code></pre></div>\n<h3 id=\"example-3---menu-from-a-sitemapdatasource\">Example 3 - Menu from a SiteMapDataSource<a class=\"anchor\" href=\"#example-3---menu-from-a-sitemapdatasource\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> m4 = <span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuController</span>({ id: <span class=\"tok-s\">&quot;m4&quot;</span>, dataSource: <span class=\"tok-f\">sm</span>() });\nm4.menuItemDataBound.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt;\n  console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;bound&quot;</span>, e.item.depth, e.item.text, e.item.value, e.item.valuePath, <span class=\"tok-t\">JSON</span>.<span class=\"tok-f\">stringify</span>(e.item.tooltip)));\n<span class=\"tok-k\">await</span> m4.<span class=\"tok-f\">dataBind</span>();\n<span class=\"tok-c\">// bound 0 Home home home &quot;Start&quot;</span>\n<span class=\"tok-c\">// bound 1 Products products home/products &quot;&quot;</span>\n<span class=\"tok-c\">// bound 2 Widgets widgets home/products/widgets &quot;All widgets&quot;</span>\n<span class=\"tok-c\">// bound 3 Blue Widget blue home/products/widgets/blue &quot;&quot;</span>\n<span class=\"tok-c\">// bound 2 Gadgets gadgets home/products/gadgets &quot;&quot;</span>\n<span class=\"tok-c\">// bound 1 About about home/about &quot;&quot;</span>\n\n<span class=\"tok-k\">const</span> ds = <span class=\"tok-f\">sm</span>(); ds.showStartingNode = <span class=\"tok-k\">false</span>;\n<span class=\"tok-k\">await</span> m4.<span class=\"tok-f\">dataBind</span>(ds);\nm4.items.<span class=\"tok-f\">map</span>(i =&gt; i.text);           <span class=\"tok-c\">// -&gt; [ 'Products', 'About' ]  (valuePaths now start at &quot;products&quot;)</span>\n<span class=\"tok-k\">await</span> m4.<span class=\"tok-f\">dataBind</span>([{ text: <span class=\"tok-s\">&quot;X&quot;</span> }, { text: <span class=\"tok-s\">&quot;Y&quot;</span> }]);\nm4.items.<span class=\"tok-f\">map</span>(i =&gt; i.valuePath);      <span class=\"tok-c\">// -&gt; [ 'X', 'Y' ]</span></code></pre></div>\n<h3 id=\"example-4---tree-checkbox-visibility-by-showcheckboxes\">Example 4 - Tree checkbox visibility by <code>showCheckBoxes</code><a class=\"anchor\" href=\"#example-4---tree-checkbox-visibility-by-showcheckboxes\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> tv = <span class=\"tok-k\">new</span> <span class=\"tok-t\">TreeViewController</span>({ id: <span class=\"tok-s\">&quot;tv&quot;</span>, expandDepth: <span class=\"tok-n\">1</span>, nodes: [\n  { text: <span class=\"tok-s\">&quot;Fruit&quot;</span>, value: <span class=\"tok-s\">&quot;fruit&quot;</span>, childNodes: [\n    { text: <span class=\"tok-s\">&quot;Apple&quot;</span>, value: <span class=\"tok-s\">&quot;apple&quot;</span> },\n    { text: <span class=\"tok-s\">&quot;Citrus&quot;</span>, value: <span class=\"tok-s\">&quot;citrus&quot;</span>, childNodes: [{ text: <span class=\"tok-s\">&quot;Lemon&quot;</span>, value: <span class=\"tok-s\">&quot;lemon&quot;</span> }, { text: <span class=\"tok-s\">&quot;Lime&quot;</span>, value: <span class=\"tok-s\">&quot;lime&quot;</span> }] } ] },\n  { text: <span class=\"tok-s\">&quot;Veg&quot;</span>, value: <span class=\"tok-s\">&quot;veg&quot;</span>, checked: <span class=\"tok-k\">true</span> } ] });\n\n<span class=\"tok-k\">for</span> (<span class=\"tok-k\">const</span> mode <span class=\"tok-k\">of</span> [<span class=\"tok-s\">&quot;None&quot;</span>, <span class=\"tok-s\">&quot;Root&quot;</span>, <span class=\"tok-s\">&quot;Parent&quot;</span>, <span class=\"tok-s\">&quot;Leaf&quot;</span>, <span class=\"tok-s\">&quot;All&quot;</span>]) {\n  tv.showCheckBoxes = mode;\n  console.<span class=\"tok-f\">log</span>(mode, <span class=\"tok-f\">flat</span>(tv.nodes).<span class=\"tok-f\">filter</span>(n =&gt; tv.<span class=\"tok-f\">shouldShowCheckBox</span>(n)).<span class=\"tok-f\">map</span>(n =&gt; n.text));\n}\n<span class=\"tok-c\">// None   []</span>\n<span class=\"tok-c\">// Root   [ 'Fruit', 'Veg' ]</span>\n<span class=\"tok-c\">// Parent [ 'Fruit', 'Citrus' ]</span>\n<span class=\"tok-c\">// Leaf   [ 'Apple', 'Lemon', 'Lime', 'Veg' ]</span>\n<span class=\"tok-c\">// All    [ 'Fruit', 'Apple', 'Citrus', 'Lemon', 'Lime', 'Veg' ]</span>\n<span class=\"tok-c\">// expandDepth 1: Fruit and Veg expanded:true, all deeper nodes expanded:false</span>\n<span class=\"tok-c\">// tv.findNode(&quot;fruit/citrus&quot;).valuePath === &quot;fruit/citrus&quot;; findNode(&quot;lemon&quot;).isLeaf === true</span></code></pre></div>\n<p>(<code>flat</code> is a helper generator you define: <code>function* flat(ns){ for(const n of ns){ yield n; yield* flat(n.childNodes);} }</code> spread into an array.)</p>\n<h3 id=\"example-5---tree-with-check-propagation-down-and-up-implemented-in-a-handler\">Example 5 - Tree with check propagation (down and up) implemented in a handler<a class=\"anchor\" href=\"#example-5---tree-with-check-propagation-down-and-up-implemented-in-a-handler\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\">tv.showCheckBoxes = <span class=\"tok-s\">&quot;All&quot;</span>;\n<span class=\"tok-k\">let</span> busy = <span class=\"tok-k\">false</span>;\ntv.treeNodeCheckChanged.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; {\n  <span class=\"tok-k\">if</span> (busy) <span class=\"tok-k\">return</span>; busy = <span class=\"tok-k\">true</span>;\n  <span class=\"tok-k\">const</span> down = (n, v) =&gt; { <span class=\"tok-k\">for</span> (<span class=\"tok-k\">const</span> c <span class=\"tok-k\">of</span> n.childNodes) { c.checked = v; <span class=\"tok-f\">down</span>(c, v); } };\n  <span class=\"tok-f\">down</span>(e.node, e.checked);\n  <span class=\"tok-k\">for</span> (<span class=\"tok-k\">let</span> p = e.node.parent; p; p = p.parent) p.checked = p.childNodes.<span class=\"tok-f\">every</span>(c =&gt; c.checked);\n  busy = <span class=\"tok-k\">false</span>;\n});\n<span class=\"tok-k\">await</span> tv.<span class=\"tok-f\">checkNode</span>(<span class=\"tok-s\">&quot;citrus&quot;</span>, <span class=\"tok-k\">true</span>);\ntv.<span class=\"tok-f\">getCheckedNodes</span>().<span class=\"tok-f\">map</span>(n =&gt; n.valuePath);\n<span class=\"tok-c\">// -&gt; [ 'fruit/citrus', 'fruit/citrus/lemon', 'fruit/citrus/lime', 'veg' ]</span>\n<span class=\"tok-k\">await</span> tv.<span class=\"tok-f\">checkNode</span>(<span class=\"tok-s\">&quot;apple&quot;</span>, <span class=\"tok-k\">true</span>);\n<span class=\"tok-c\">// -&gt; [ 'fruit', 'fruit/apple', 'fruit/citrus', 'fruit/citrus/lemon', 'fruit/citrus/lime', 'veg' ]</span>\n<span class=\"tok-k\">await</span> tv.<span class=\"tok-f\">checkNode</span>(<span class=\"tok-s\">&quot;lime&quot;</span>, <span class=\"tok-k\">false</span>);\n<span class=\"tok-c\">// -&gt; [ 'fruit/apple', 'fruit/citrus/lemon', 'veg' ]</span>\n<span class=\"tok-k\">await</span> tv.<span class=\"tok-f\">checkNode</span>(<span class=\"tok-s\">&quot;nope&quot;</span>, <span class=\"tok-k\">true</span>);    <span class=\"tok-c\">// -&gt; false</span></code></pre></div>\n<h3 id=\"example-6---expandcollapseselect-events-with-a-sitemap-bound-tree\">Example 6 - Expand/collapse/select events with a SiteMap-bound tree<a class=\"anchor\" href=\"#example-6---expandcollapseselect-events-with-a-sitemap-bound-tree\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> t2 = <span class=\"tok-k\">new</span> <span class=\"tok-t\">TreeViewController</span>({ id: <span class=\"tok-s\">&quot;t2&quot;</span>, dataSource: <span class=\"tok-f\">sm</span>(), expandDepth: <span class=\"tok-n\">0</span> });\n<span class=\"tok-k\">for</span> (<span class=\"tok-k\">const</span> k <span class=\"tok-k\">of</span> [<span class=\"tok-s\">&quot;selectedNodeChanged&quot;</span>, <span class=\"tok-s\">&quot;treeNodeExpanded&quot;</span>, <span class=\"tok-s\">&quot;treeNodeCollapsed&quot;</span>, <span class=\"tok-s\">&quot;treeNodeDataBound&quot;</span>])\n  t2[k].<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;evt&quot;</span>, k, e.node.text));\nt2.stateChanged.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;state&quot;</span>, e.reason));\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">dataBind</span>();\n<span class=\"tok-c\">// evt treeNodeDataBound Home ... Products, Widgets, Blue Widget, Gadgets, About / state dataBind</span>\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">expandNode</span>(<span class=\"tok-s\">&quot;products&quot;</span>);    <span class=\"tok-c\">// evt treeNodeExpanded Products / state expandNode -&gt; true</span>\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">expandNode</span>(<span class=\"tok-s\">&quot;products&quot;</span>);    <span class=\"tok-c\">// -&gt; false (already expanded, no events)</span>\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">toggleNode</span>(<span class=\"tok-s\">&quot;products&quot;</span>);    <span class=\"tok-c\">// collapses -&gt; true;  next toggleNode expands again -&gt; true</span>\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">toggleNode</span>(<span class=\"tok-s\">&quot;zzz&quot;</span>);         <span class=\"tok-c\">// -&gt; false</span>\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">expandAll</span>();               <span class=\"tok-c\">// only &quot;state expandAll&quot; (no per-node events)</span>\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">collapseAll</span>();\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">expandToDepth</span>(<span class=\"tok-n\">2</span>);          <span class=\"tok-c\">// Home:true Products:true Widgets:false Blue Widget:false Gadgets:false About:true</span>\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">selectNode</span>(<span class=\"tok-s\">&quot;widgets&quot;</span>);     <span class=\"tok-c\">// evt selectedNodeChanged Widgets / state selectNode -&gt; true</span>\nt2.<span class=\"tok-f\">findNode</span>(<span class=\"tok-s\">&quot;about&quot;</span>).selectable = <span class=\"tok-k\">false</span>;\n<span class=\"tok-k\">await</span> t2.<span class=\"tok-f\">selectNode</span>(<span class=\"tok-s\">&quot;about&quot;</span>);       <span class=\"tok-c\">// -&gt; false; selectedNode still &quot;Widgets&quot;</span></code></pre></div>\n<p>Note that after <code>dataBind</code> with <code>expandDepth: 0</code> every node is collapsed, including the root. <code>expandToDepth(2)</code> expands nodes whose <code>depth &lt; 2</code> (Home, Products, About) and collapses the rest.</p>\n<h3 id=\"example-7---breadcrumb-from-a-site-map\">Example 7 - Breadcrumb from a site map<a class=\"anchor\" href=\"#example-7---breadcrumb-from-a-site-map\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> sp = <span class=\"tok-k\">new</span> <span class=\"tok-t\">SiteMapPathController</span>({ id: <span class=\"tok-s\">&quot;bc&quot;</span>, siteMapProvider: <span class=\"tok-f\">sm</span>(), currentUrlOrKey: <span class=\"tok-s\">&quot;/products/widgets/blue&quot;</span> });\nsp.itemCreated.<span class=\"tok-f\">subscribe</span>((_s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;created&quot;</span>, e.item.itemType, e.item.text));\n<span class=\"tok-k\">const</span> items = <span class=\"tok-k\">await</span> sp.<span class=\"tok-f\">dataBind</span>();\nitems.<span class=\"tok-f\">map</span>(i =&gt; [i.itemType, i.text, i.url, i.isLink]);\n<span class=\"tok-c\">// -&gt; [ ['Root','Home','/',true], ['Parent','Products','/products',true],</span>\n<span class=\"tok-c\">//      ['Parent','Widgets','/products/widgets',true], ['Current','Blue Widget','/products/widgets/blue',false] ]</span>\nsp.<span class=\"tok-f\">renderText</span>();                                      <span class=\"tok-c\">// -&gt; Home &gt; Products &gt; Widgets &gt; Blue Widget</span>\n\nsp.pathDirection = <span class=\"tok-s\">&quot;CurrentToRoot&quot;</span>; sp.pathSeparator = <span class=\"tok-s\">&quot; / &quot;</span>; <span class=\"tok-k\">await</span> sp.<span class=\"tok-f\">dataBind</span>();\nsp.<span class=\"tok-f\">renderText</span>();                                      <span class=\"tok-c\">// -&gt; Blue Widget / Widgets / Products / Home</span></code></pre></div>\n<h3 id=\"example-8---limiting-parent-levels-current-as-link-unknown-keys\">Example 8 - Limiting parent levels, current-as-link, unknown keys<a class=\"anchor\" href=\"#example-8---limiting-parent-levels-current-as-link-unknown-keys\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\">sp.pathDirection = <span class=\"tok-s\">&quot;RootToCurrent&quot;</span>; sp.renderCurrentNodeAsLink = <span class=\"tok-k\">true</span>;\nsp.parentLevelsDisplayed = <span class=\"tok-n\">0</span>; <span class=\"tok-k\">await</span> sp.<span class=\"tok-f\">dataBind</span>();\nsp.<span class=\"tok-f\">renderText</span>();                       <span class=\"tok-c\">// -&gt; Home / Blue Widget   (isLink: [true, true])</span>\nsp.parentLevelsDisplayed = <span class=\"tok-n\">1</span>; <span class=\"tok-k\">await</span> sp.<span class=\"tok-f\">dataBind</span>();\nsp.<span class=\"tok-f\">renderText</span>();                       <span class=\"tok-c\">// -&gt; Home / Widgets / Blue Widget</span>\n<span class=\"tok-k\">await</span> sp.<span class=\"tok-f\">dataBind</span>(<span class=\"tok-s\">&quot;about&quot;</span>);            <span class=\"tok-c\">// [Root, Current] - &quot;About&quot; has no url, so Root &quot;Home&quot; is a link, Current is a link only because renderCurrentNodeAsLink</span>\n<span class=\"tok-k\">await</span> sp.<span class=\"tok-f\">dataBind</span>(<span class=\"tok-s\">&quot;nothing&quot;</span>);          <span class=\"tok-c\">// items cleared (getItems().length === 0) but sp.currentUrlOrKey === &quot;nothing&quot;</span>\n<span class=\"tok-k\">await</span> sp.<span class=\"tok-f\">dataBind</span>(<span class=\"tok-s\">&quot;home&quot;</span>);             <span class=\"tok-c\">// single item: [ 'Current' ]</span>\n<span class=\"tok-k\">const</span> none = <span class=\"tok-k\">new</span> <span class=\"tok-t\">SiteMapPathController</span>({ id: <span class=\"tok-s\">&quot;n&quot;</span> });\n(<span class=\"tok-k\">await</span> none.<span class=\"tok-f\">dataBind</span>(<span class=\"tok-s\">&quot;x&quot;</span>)).length;     <span class=\"tok-c\">// -&gt; 0   (no provider)</span></code></pre></div>\n<p>(<code>about</code> matches by <code>key</code> because that node has no <code>url</code>; lookups match either <code>key</code> or <code>url</code>.)</p>\n<h3 id=\"example-9---mutating-a-node-after-binding-refresh-the-hierarchy\">Example 9 - Mutating a node after binding (refresh the hierarchy)<a class=\"anchor\" href=\"#example-9---mutating-a-node-after-binding-refresh-the-hierarchy\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> pre = <span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuItem</span>({ text: <span class=\"tok-s\">&quot;P&quot;</span>, childItems: [{ text: <span class=\"tok-s\">&quot;Q&quot;</span> }] });\nconsole.<span class=\"tok-f\">log</span>(pre.childItems[<span class=\"tok-n\">0</span>].depth, <span class=\"tok-t\">JSON</span>.<span class=\"tok-f\">stringify</span>(pre.valuePath)); <span class=\"tok-c\">// -&gt; 0 &quot;&quot;</span>\nm4.<span class=\"tok-f\">setItems</span>([pre]);\nconsole.<span class=\"tok-f\">log</span>(pre.childItems[<span class=\"tok-n\">0</span>].depth, pre.childItems[<span class=\"tok-n\">0</span>].valuePath);   <span class=\"tok-c\">// -&gt; 1 P/Q</span>\n\n<span class=\"tok-c\">// after adding a child manually:</span>\npre.childItems.<span class=\"tok-f\">push</span>(<span class=\"tok-k\">new</span> <span class=\"tok-t\">MenuItem</span>({ text: <span class=\"tok-s\">&quot;R&quot;</span> }));\npre.<span class=\"tok-f\">refreshHierarchy</span>(<span class=\"tok-k\">undefined</span>, <span class=\"tok-n\">0</span>);                                  <span class=\"tok-c\">// recompute depth/valuePath/parent for the subtree</span></code></pre></div>\n<h3 id=\"example-10---distinct-ids-without-namingcontainer\">Example 10 - Distinct ids without NamingContainer<a class=\"anchor\" href=\"#example-10---distinct-ids-without-namingcontainer\" aria-label=\"Link to this section\">#</a></h3>\n<p>Because the naming module is empty (section 7), compose ids yourself.</p>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">typescript</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-typescript\"><span class=\"tok-k\">const</span> scopedId = (parent: string, child: string) =&gt; <span class=\"tok-s\">`${parent}_${child}`</span>;\n<span class=\"tok-k\">const</span> tvA = <span class=\"tok-k\">new</span> <span class=\"tok-t\">TreeViewController</span>({ id: <span class=\"tok-f\">scopedId</span>(<span class=\"tok-s\">&quot;panelA&quot;</span>, <span class=\"tok-s\">&quot;tree&quot;</span>) });\n<span class=\"tok-k\">const</span> tvB = <span class=\"tok-k\">new</span> <span class=\"tok-t\">TreeViewController</span>({ id: <span class=\"tok-f\">scopedId</span>(<span class=\"tok-s\">&quot;panelB&quot;</span>, <span class=\"tok-s\">&quot;tree&quot;</span>) });\nconsole.<span class=\"tok-f\">log</span>(tvA.id, tvB.id);   <span class=\"tok-c\">// -&gt; panelA_tree panelB_tree</span></code></pre></div>\n<hr>\n"},"gotchas-checklist":{"overview":"<ul><li><code>valuePath</code> uses <code>value</code> (not <code>text</code>), and is <code>&quot;&quot;</code> until <code>refreshHierarchy</code> runs (done by <code>setItems</code>, <code>setNodes</code>, <code>dataBind</code>).</li><li><code>findItem</code>/<code>findNode</code> match <code>valuePath</code> or <code>value</code> or <code>text</code>, first in pre-order; duplicates are ambiguous.</li><li>Menu: <code>clickItem</code> returns <code>true</code> for non-selectable (but enabled) items without selecting them; disabled items produce no event.</li><li>Menu: <code>staticDisplayLevels</code> min 1 and <code>maximumDynamicDisplayLevels</code> min 0 are enforced only in the constructor.</li><li>Menu keeps no flyout-open state; <code>disappearAfter</code>, <code>orientation</code> are adapter hints. TreeView <code>showLines</code> and SiteMapPath <code>showToolTips</code> are also adapter hints.</li><li>TreeView never propagates check state; <code>getCheckedNodes</code> includes nodes whose checkbox is hidden by <code>showCheckBoxes</code>.</li><li><code>expandDepth &gt;= 0</code> overrides per-node <code>expanded</code> on every <code>setNodes</code>/<code>dataBind</code>; <code>expandAll</code>, <code>collapseAll</code>, <code>expandToDepth</code> emit only <code>stateChanged</code>.</li><li><code>selected: true</code> in options does not populate <code>selectedItem</code>/<code>selectedNode</code>.</li><li><code>SiteMapDataSource</code> conversion drops <code>roles</code>, and <code>enabled</code>/<code>checked</code>/etc. take defaults.</li><li>SiteMapPath records an unknown <code>currentUrlOrKey</code> even when the lookup fails; <code>dataBind</code> returns the internal array while <code>getItems()</code> returns a copy.</li><li><code>NamingContainer</code>/<code>ClientID</code>/<code>UniqueID</code> are not implemented; the naming module is empty.</li></ul>"}};
export default area;
